/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ImportSummaryView, ImportSummaryContext
 *   Functions: importUploadsWaiting, importIdentityAnswers, importSummaryView
 * Internal
 *   Functions: isRecord, left, filesCreditOnlyPlaceholders
 * @end-catalog */

/**
 * The server-computed part of an import's Review and publish summary (GET /imports/:id/lookup `summary`), so the Web never
 * decides on its own what Publish waits for: whether the import appends, which work Publish waits for, whether a new Album's
 * credit rests only on a placeholder, how many identity rows still need an answer, whether this server can run metadata
 * lookup, each shown Luna suggestion's tick state and the analysis budget the Analyze confirmation shows. Lookup answers stay
 * in the lookup view (`needsAnswer`). The publish transaction rechecks all of it, the upload wait with importUploadsWaiting.
 * Pure. Owner rules: docs/business-rules.md (Administrator Album Imports, Review and publish summary and Luna bullets).
 */
import { ADMIN_IMPORT_LIMITS } from './adminImportContract';
import { boundArtistDecision, boundLabelDecision, type ImportDecisionV2, type ImportDraftV2 } from './adminImportDraft';
import { importDraftV2View, importProjectV2View, legacyManifestView } from './adminImportDraftCompat';
import { lunaTick, shownPendingSuggestions, type LunaTick } from './adminImportLunaTicks';
import { importUploadSettled } from './adminImportMediaTypes';
import type { AdminImportDocument } from './adminImportService';
import { importTagsV2View } from './adminImportTags';
import { importAutomationMarkers } from './adminImportValueState';
import { isPlaceholderCredit } from '../lookup/lookupIdentifiers';
import { isBlockingLookupState, type MetadataLookupRecord } from '../lookup/metadataLookupRecord';

export type ImportSummaryView = {
    /** An explicit Album reuse: the draft's Album values, entries, label, cover and Album lookup conflicts are not applied. */
    append: boolean;
    waiting: { uploads: boolean; lookup: boolean; analysis: boolean };
    /** A new Album without a primary Artist entry whose files or applied lookup release credit only a placeholder. */
    placeholderOnly: boolean;
    luna: { id: string; tick: LunaTick }[];
    /** What is left: analysis runs and provider calls for this project, and provider calls today across the deployment. */
    analysis: { runs: number; attempts: number; daily: number };
    /** Whether this server can run metadata lookup at all; without it the summary offers Luna and no lookup step. */
    lookupAvailable: boolean;
    /** Identity rows of the saved draft that neither a saved decision nor a preselection answers (importIdentityAnswers). */
    identityAnswers: number;
};
/**
 * What the summary reads beside the project: the time it is read at, provider calls used today, the lookup configuration and the
 * identity rows left to answer.
 */
export type ImportSummaryContext = { now: Date; dailyAttemptsUsed: number; lookupAvailable: boolean; identityAnswers: number };

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const left = (limit: number, used: unknown) => Math.max(0, limit - (Number.isSafeInteger(used) && (used as number) > 0 ? used as number : 0));

/**
 * Whether every manifest file has confirmed version-2 tag evidence naming album-level credits (album artists, else artists) and
 * all of them are placeholders such as Various Artists.
 */
function filesCreditOnlyPlaceholders(files: readonly { slotId: string }[], doc: AdminImportDocument): boolean {
    const assets = doc.media?.assets ?? [];
    const credits = files.map(file => {
        const tags = importTagsV2View(assets.find(asset => asset.slotId === file.slotId && asset.state === 'ready')?.tags);
        return tags?.version === 2 ? (tags.albumArtists.length ? tags.albumArtists : tags.artists) : [];
    });
    return files.length > 0 && credits.every(names => names.length > 0 && names.every(name => isPlaceholderCredit(name)));
}

/**
 * Whether Publish waits for uploads: any staged upload (a file or a cover) is still in flight, pending with a PUT that can
 * still land (importUploadSettled), or a manifest file whose track needs its bytes lacks a confirmed upload. A track decided
 * `skip` is never published and one decided `reuse` keeps the existing member's media, so neither needs its file. The summary
 * passes the saved decisions; the publish transaction its frozen ones, preselections included.
 */
export function importUploadsWaiting(doc: Pick<AdminImportDocument, 'manifest' | 'media'>, decisions: readonly unknown[], now: Date): boolean {
    const files = legacyManifestView(doc.manifest).files, assets = doc.media?.assets ?? [];
    const unneeded = (slotId: string) => decisions.some(decision => isRecord(decision) && decision.scope === 'track' && decision.slotId === slotId
        && (decision.action === 'skip' || decision.action === 'reuse'));
    return assets.some(asset => asset.state === 'pending' && !importUploadSettled(asset, now))
        || files.some(file => !unneeded(file.slotId) && !assets.some(asset => asset.slotId === file.slotId && asset.state === 'ready'));
}

/**
 * How many identity rows of `draft` neither an explicit decision nor a preselection answers with a reuse or a new record, as the
 * publication confirmation counts the rows that need a decision: the Album, each track that is not skipped and, unless the
 * Album is reused (an append applies neither), each Artist entry and the label.
 */
export function importIdentityAnswers(draft: ImportDraftV2, decisions: readonly ImportDecisionV2[], preselections: readonly ImportDecisionV2[]): number {
    const all = [...decisions, ...preselections], album = all.find(decision => decision.scope === 'album');
    const tracks = draft.tracks.map(track => all.find(decision => decision.scope === 'track' && decision.slotId === track.slotId)).filter(decision => decision?.action !== 'skip');
    const rows = [album, ...tracks, ...album?.action === 'reuse' ? [] : [...draft.album.artists.map(entry => boundArtistDecision(all, entry)),
        ...draft.album.label ? [boundLabelDecision(all, draft.album.label)] : []]];
    return rows.filter(decision => decision?.action !== 'reuse' && decision?.action !== 'create-distinct').length;
}

/**
 * The summary state of `doc` with its lookup record (null before any run) and `context`. Uploads are waited for as
 * importUploadsWaiting says with the saved decisions, lookup while its run is queued, running or retrying automatically (value
 * application shares that step), and analysis while it is queued or running. A stored manifest in a shape this release does not
 * know reads as its sanitized view, as the editor shows it.
 */
export function importSummaryView(doc: AdminImportDocument, lookup: Partial<MetadataLookupRecord> | null, context: ImportSummaryContext): ImportSummaryView {
    const id = doc._id.toHexString(), manifest = legacyManifestView(doc.manifest);
    const draft = importDraftV2View(doc.draft, manifest, id), origins = importProjectV2View(doc)?.draftOrigins;
    const applied = isRecord(lookup?.applied) ? lookup!.applied : null;
    const markers = importAutomationMarkers(draft, origins, Array.isArray(applied?.values) ? applied!.values : []);
    const tagPaths = new Set<string>(markers.automaticPaths.filter(path => !markers.lookupPaths.includes(path)));
    const decisions = Array.isArray(doc.decisions) ? doc.decisions : [];
    const append = decisions.some(decision => isRecord(decision) && decision.scope === 'album' && decision.action === 'reuse');
    const appliedPlaceholder = Array.isArray(applied?.flagged) && applied!.flagged.some(flag => isRecord(flag) && flag.path === 'album.artists' && flag.reason === 'placeholder');
    return {
        append,
        waiting: {
            uploads: importUploadsWaiting(doc, decisions, context.now),
            lookup: isBlockingLookupState(lookup?.state) || doc.lookupGate?.blocking === true,
            analysis: ['queued', 'running'].includes(doc.analysis?.state)
        },
        placeholderOnly: !append && !draft.album.artists.some(entry => entry.role === 'primary') && (appliedPlaceholder || filesCreditOnlyPlaceholders(manifest.files, doc)),
        luna: shownPendingSuggestions(doc).map(suggestion => ({ id: suggestion.id, tick: lunaTick(draft, origins, suggestion, tagPaths) })),
        analysis: { runs: left(ADMIN_IMPORT_LIMITS.generations, doc.analysis?.generation), attempts: left(ADMIN_IMPORT_LIMITS.attempts, doc.attemptsUsed),
            daily: left(ADMIN_IMPORT_LIMITS.dailyAttempts, context.dailyAttemptsUsed) },
        lookupAvailable: context.lookupAvailable,
        identityAnswers: context.identityAnswers
    };
}
